input.sparql:
SELECT ?p ?plabel ?cls WHERE {
  ?z brick:hasSubgraph ?g .
  ?z brick:hasPoint ?p .
  FILTER(str(?z) = "urn:brick:zone:Core_mid" || str(?z) = "ref:zone/Core_mid")
}

SELECT ?z ?zlabel WHERE {
  ?z a brick:Zone .
  ?z rdfs:label ?zlabel .
  FILTER(CONTAINS(str(?zlabel), "Core_mid"))
}

SELECT ?p ?label ?cls ?tsid WHERE {
  ?zone a brick:Zone .
  ?zone rdfs:label "Core_mid" .
  ?zone brick:hasPoint ?p .
  OPTIONAL { ?p rdfs:label ?label }
  OPTIONAL { ?p a ?cls }
  OPTIONAL { ?p ref:hasTimeseriesId ?tsid }
}

SELECT ?p ?label ?cls ?rel WHERE {
  ?zone a brick:Zone .
  ?zone rdfs:label "Core_mid" .
  ?zone ?rel ?p .
  OPTIONAL { ?p rdfs:label ?label }
  OPTIONAL { ?p a ?cls }
}

